import { useQuery } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";

export interface VocabularyItem {
  id: string;
  term: string;
  meaning: string;
  example_sentence: string;
}

export interface QuizItem {
  id: string;
  question: string;
  answer: string;
}

export interface EducationalContent {
  vocabulary: VocabularyItem[];
  quiz: QuizItem[];
}

/** Vocabulary + quiz generated by Agent 7 (EducationalAgent) — runs off the
 * critical path (see worker/agents/educational_agent.py), so this can return
 * empty lists even once the job reaches ready_for_review; there is no
 * separate "still generating" status to tell that case apart from "Gemini
 * returned nothing", see api/routers/jobs.py::get_educational_content. */
export function useEducationalContent(jobId: string | undefined) {
  return useQuery({
    queryKey: ["educational-content", jobId],
    queryFn: () =>
      apiFetch<EducationalContent>(`/jobs/${jobId}/educational-content`),
    enabled: !!jobId,
  });
}
